{
  "marker": "TASK_COMPLETE",
  "carryover": {
    "COMPLETED": "All hypotheses refuted: H-23bf9a, H-6472ba, H-54ac2e, H-1418d9.",
    "REMAINING": "-",
    "DECISIONS": "The 13 revenue rows for Apple FY2022 arise from quarterly year‑to‑date reporting in 10‑Q filings plus the annual 10‑K filing, using a single XBRL concept.",
    "CONTEXT": "Evidence shows only one revenue concept (RevenueFromContractWithCustomerExcludingAssessedTax) appears, each filing has a unique accession number, and the distribution is 10 rows from 10‑Q and 3 rows from 10‑K."
  },
  "answer": {
    "summary": "Apple reports revenue once per filing. For FY2022 it submitted three 10‑K filings (including the annual report and two prior‑year amendments) and ten 10‑Q filings, each containing a single revenue fact for its respective period. This yields 3 + 10 = 13 rows, not duplicate concepts or amendments within the same period.",
    "claims": [
      {
        "text": "Apple FY2022 revenue rows consist of 3 rows with form_type='10-K' and 10 rows with form_type='10-Q'.",
        "evidence": ["E-db2094"]
      },
      {
        "text": "Only the concept 'RevenueFromContractWithCustomerExcludingAssessedTax' appears for Apple FY2022; the 'Revenues' concept has zero rows.",
        "evidence": ["E-038ee2", "E-b4663b"]
      },
      {
        "text": "Each fiscal period in FY2022 has exactly one distinct accession number, indicating no duplicate filings for the same period.",
        "evidence": ["E-0d779b"]
      }
    ],
    "inferences": [
      {
        "text": "The 10‑Q rows represent cumulative year‑to‑date periods (e.g., Sep 27 2020‑Mar 27 2021, Sep 27 2020‑Jun 26 2021, etc.) while the 10‑K rows cover full fiscal years, which explains the pattern of periods seen in the data.",
        "basis": "Claims about form_type distribution and period ranges from E-71274f and E-d47573"
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-23bf9a",
        "status": "refuted",
        "evidence": ["E-0d779b"],
        "why": "No period has more than one accession number, so amendments/restatements do not create duplicate rows."
      },
      {
        "id": "H-6472ba",
        "status": "refuted",
        "evidence": ["E-db2094", "E-0d779b"],
        "why": "Quarterly plus annual filings give 4 + 1 = 5 rows per concept, but we observe 10 + 3 rows; the excess comes from year‑to‑date quarters, not extra filings."
      },
      {
        "id": "H-54ac2e",
        "status": "refuted",
        "evidence": ["E-16ee26", "E-db2094"],
        "why": "Only one XBRL concept appears; no dimensional segmentation splits rows."
      },
      {
        "id": "H-1418d9",
        "status": "refuted",
        "evidence": ["E-b4663b", "E-038ee2"],
        "why": "The 'Revenues' concept has zero rows for Apple FY2022, so two concepts are not used."
      }
    ]
  }
}
